            return Err(invalid(0));
        }
        self.slice(h)
    }
    fn references(&self, h: JobBuffer<u32>, scope: u64) -> Result<&[u32]> {
        self.require_pool(h, RasterPool::Grid)?;
        if self.checked(h)?.scope != scope {
            return Err(invalid(0));
        }
        self.slice(h)
    }
}
struct Split<'a> {
