impl Split<'_> {
    fn slice<T: JobElement>(&self, h: JobBuffer<T>, pool: RasterPool) -> Result<&[T]> {
        self.slice_scoped(h, pool, self.scope)
    }
    fn slice_scoped<T: JobElement>(
        &self,
        h: JobBuffer<T>,
        pool: RasterPool,
        scope: u64,
    ) -> Result<&[T]> {
        let (owner, slot, serial) = h.identity();
        if owner != self.owner || slot == self.a || slot == self.b {
            return Err(invalid(0));
        }
        let s = if slot < self.a {
            self.head.get(slot)
        } else if slot < self.b {
            self.middle.get(slot - self.a - 1)
        } else {
            self.tail.get(slot - self.b - 1)
        }
        .ok_or_else(|| invalid(0))?;
        if !s.active || s.serial != serial || s.pool != pool || s.scope != scope {
            return Err(invalid(0));
        }
        Ok(T::get(&s.data).ok_or_else(|| invalid(0))?)
    }
}
impl CacheRead for Split<'_> {
    fn cells(&self, h: JobBuffer<GridCell>, scope: u64) -> Result<&[GridCell]> {
        self.slice_scoped(h, RasterPool::Grid, scope)
