        &mut self, ctx: &mut DefinitionContext<'src, '_>, kind: DefinitionKind,
        element: ElementId, owner: DefinitionOwner, transform: Affine, bounds: [f64; 4],
        style: &vexel_svg_css::CssPaint<'src>, control: &mut dyn WorkControl,
