        control.charge(WorkKind::ReferenceProbe, 1).map_err(stopped)?;
        let child = view.scene(mask.content).ok_or_else(|| invalid(mask.source_offset))?;
        crate::validate::viewport(child.viewport)?;
        validate_mask_closure(child, stack, depth + 1, visits, control)?;
    }
