pub(crate) fn paint_view<V: ViewportRead, A: Copy>(
    scene: SceneView<'_, V, A>,
    value: &Paint,
    control: &mut dyn WorkControl,
) -> Result<()> {
    charge(control, WorkKind::PaintVisit)?;
    value.stops.require(scene.stops.len(), 0)?;
    if value.stops.count > 256 {
        return Err(limit(LimitKind::PaintStops));
    }
    stops(
        value.stops.slice(scene.stops).ok_or_else(|| invalid(0))?,
        control,
    )?;
    if !finite(&value.coordinates)
        || (crate::ordered_bounds_extent(value.bounds).is_none() || !value.bounds.into_iter().all(coord))
        || ![
            value.user_inverse,
            value.gradient_inverse,
            value.pattern_inverse,
        ]
        .into_iter()
        .all(affine_valid)
        || !value.pattern_opacity.is_finite()
        -> Result<JobRenderOutput>;
}
/// All capabilities are explicit obligations on the actual production engine.
pub trait CommonRasterKernel:
    CommonKernelResources + CommonIndexKernel + CommonSampleKernel + CommonFlatKernel {}

/// Guard before calling the lower renderer. Its output remains in the same job.
pub fn render_common_pattern(kernel: &mut dyn CommonRasterKernel,
    request: &StaticPatternRequest<'_>, options: RenderOptions, job: &mut RasterJob,
    control: &mut dyn WorkControl) -> Result<JobRenderOutput> {
    let input = request.child.input();
    input.validate_job(job, control)?;
    let output = kernel.render_flat(input,
        TableRange { first: 0, count: input.shapes().len() }, options, job, control)?;
    output.validate(job)?;
    if Some(output.generation) != input.static_generation()
        || output.width != request.descriptor.width || output.height != request.descriptor.height {
        job.release(output.pixels)?;
        return Err(invalid(request.descriptor.error_offset));
    }
    Ok(output)
}

