/// Decoder owns its actual token, builder and providers in disjoint fields.
/// Mandatory suspension prevents the late parser from running before resume.
struct Session<'a> {
    document: &'a LexicalDocument, builder: SceneBuilder, draft: Option<DraftToken>,
    tickets: PatternTickets, state: u8, provider: Provider, ledger: ChargeLedger,
    parser_calls: usize,
}
impl ScopedProductionDecodeSession for Session<'_> {
    fn step<'s>(&'s mut self, _:u64, job:&RasterJob,
        operations:&mut dyn ScopedProductionDecodeOperations,c:&mut dyn WorkControl)
        -> Result<ScopedDecodeEvent<'s>> {
        if self.state==1 { return Err(error()); } // outstanding barrier
        if self.state==0 {
            let shared=DecodeSource::new(self.document,c)?;
            let draft=self.draft.as_ref().unwrap();
            // This is the actual token owned by the decoder, not reconstructed.
            text(operations,&mut self.builder,draft,&shared,self.document,&mut self.provider,&mut self.ledger,c)?;
            let root=self.builder.root_id();
            let shape=self.builder.append_shape(root,shape(self.document.source()),c)?;
            let map=self.builder.traversal_scene(root)?.shape(shape).unwrap().source;
            let mut viewport=viewport(); viewport.width=1;viewport.height=1;
            viewport.view_width=1.;viewport.view_height=1.;viewport.aspect.none=true;
            let child=self.builder.new_scene(viewport)?;
            let child_draft=self.builder.begin_draft(child)?;
            self.builder.append_shape(child,shape_input(self.document),c)?;
            self.builder.commit_draft(&child_draft,c)?;self.builder.seal(child,c)?;
            // The media request committed; the pattern owns its real request.
            self.builder.begin_request(draft,c)?;
            // Child must be newly owned by the request. Allocate it at this point.
            let child2=self.builder.new_scene(viewport)?;
            let cd=self.builder.begin_draft(child2)?;
            self.builder.append_shape(child2,shape_input(self.document),c)?;
            self.builder.commit_draft(&cd,c)?;self.builder.seal(child2,c)?;
            let desc=PatternDescriptor {definition:element(self.document,b\"pattern\"),width:1,height:1,
                tile_width:1.,tile_height:1.,content_transform:identity(),error_offset:0};
            let mapping=PatternMapping {tile_origin:[0.;2],user_to_base:identity(),pattern_transform:identity(),
